import{_ as i,c as a,o as e,aj as r}from"./chunks/framework.CynFBi0q.js";const u=JSON.parse('{"title":"Python 高级爬虫实战 - 知识结构目录","description":"","frontmatter":{},"headers":[],"relativePath":"handbook/python-crawler/index.md","filePath":"handbook/python-crawler/index.md","lastUpdated":1782660684000}'),o={name:"handbook/python-crawler/index.md"};function h(t,l,n,d,s,c){return e(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="python-高级爬虫实战-知识结构目录" tabindex="-1">Python 高级爬虫实战 - 知识结构目录 <a class="header-anchor" href="#python-高级爬虫实战-知识结构目录" aria-label="Permalink to “Python 高级爬虫实战 - 知识结构目录”">​</a></h1><h2 id="课程概览" tabindex="-1">课程概览 <a class="header-anchor" href="#课程概览" aria-label="Permalink to “课程概览”">​</a></h2><h3 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to “课程定位”">​</a></h3><p>针对有 Python 基础的开发工程师，系统掌握 Web 反爬破解技术，挑战高级爬虫工程师高薪岗位</p><h3 id="核心特色" tabindex="-1">核心特色 <a class="header-anchor" href="#核心特色" aria-label="Permalink to “核心特色”">​</a></h3><ul><li><strong>反爬全面覆盖</strong>：加密登录破解、逆向重构、Cookie 池管理、浏览器调度、字体加密破解</li><li><strong>实战驱动</strong>：每个章节配套真实网站实战练习，直接对标生产环境</li><li><strong>架构进阶</strong>：从单机爬虫到分布式爬虫架构，掌握海量数据抓取方案</li><li><strong>工程化思维</strong>：代理池搭建、Cookie 池管理、分布式部署、海量存储一体化方案</li></ul><h3 id="课程结构" tabindex="-1">课程结构 <a class="header-anchor" href="#课程结构" aria-label="Permalink to “课程结构”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>内容</th></tr></thead><tbody><tr><td>章节</td><td>11章</td></tr><tr><td>时长</td><td>22小时30分钟</td></tr><tr><td>难度</td><td>高级</td></tr><tr><td>讲师</td><td>小布老师（全栈 Python 工程师，中国人民银行金融数据中心爬虫技术专家）</td></tr><tr><td>适用</td><td>有 Python 基础，想进阶高级爬虫工程师</td></tr></tbody></table><hr><h2 id="第一章-爬虫进阶-突破-web-反爬-课程导学" tabindex="-1">第一章：爬虫进阶 - 突破 Web 反爬（课程导学） <a class="header-anchor" href="#第一章-爬虫进阶-突破-web-反爬-课程导学" aria-label="Permalink to “第一章：爬虫进阶 - 突破 Web 反爬（课程导学）”">​</a></h2><h3 id="教学目标" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>了解课程整体脉络与学习路线</li><li>搭建开发环境</li><li>明确爬虫工程师的学习方向与重点</li></ol><h3 id="学习痛点" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>不知道爬虫进阶该学什么，学习路线不清晰</li><li>环境搭建不完整，后续学习频频卡壳</li><li>对爬虫工程师的职业发展方向模糊</li></ul><h3 id="章节内容" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_1-1-课程导学" tabindex="-1">1.1 课程导学 <a class="header-anchor" href="#_1-1-课程导学" aria-label="Permalink to “1.1 课程导学”">​</a></h4><ul><li>爬虫进阶之破解 Web 端反爬技术 - 课程导学（07:00）</li><li>课程整体架构与学习路径图</li></ul><h4 id="_1-2-爬虫工程师学习建议" tabindex="-1">1.2 爬虫工程师学习建议 <a class="header-anchor" href="#_1-2-爬虫工程师学习建议" aria-label="Permalink to “1.2 爬虫工程师学习建议”">​</a></h4><ul><li>给所有爬虫工程师的学习建议（19:37）</li><li>爬虫重点学习方向梳理</li><li>爬虫工程师该何去何从？（讨论题）</li></ul><h4 id="_1-3-开发环境搭建" tabindex="-1">1.3 开发环境搭建 <a class="header-anchor" href="#_1-3-开发环境搭建" aria-label="Permalink to “1.3 开发环境搭建”">​</a></h4><ul><li>课程开发环境搭建文档</li><li>Python 环境、IDE 配置、抓包工具安装</li></ul><h3 id="本章知识点" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>爬虫工程师能力模型与成长路径</li><li>反爬技术全景图</li><li>学习环境准备清单</li></ul><hr><h2 id="第二章-必须掌握的-http-网络基础知识" tabindex="-1">第二章：必须掌握的 HTTP 网络基础知识 <a class="header-anchor" href="#第二章-必须掌握的-http-网络基础知识" aria-label="Permalink to “第二章：必须掌握的 HTTP 网络基础知识”">​</a></h2><h3 id="教学目标-1" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-1" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>深入理解 HTTPS 的安全机制与加密原理</li><li>掌握 HTTP 状态码在爬虫调试中的应用</li><li>识别 HTTP 请求头中暴露爬虫身份的信息</li><li>掌握 HTTP 协议版本演进与爬虫适配</li><li>解决 HTTPS 证书认证问题</li></ol><h3 id="学习痛点-1" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-1" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>不理解 HTTPS 加密原理，遇到 SSL 错误不知道怎么处理</li><li>请求头配置不当，被网站轻易识别为爬虫</li><li>不清楚 HTTP/1.1 vs HTTP/2 的差异，无法适配目标网站</li><li>证书认证失败时不知道如何绕过</li></ul><h3 id="章节内容-1" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容-1" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_2-1-https-安全机制" tabindex="-1">2.1 HTTPS 安全机制 <a class="header-anchor" href="#_2-1-https-安全机制" aria-label="Permalink to “2.1 HTTPS 安全机制”">​</a></h4><ul><li>为什么 HTTPS 是安全的？（上）（10:50）</li><li>为什么 HTTPS 是安全的？（下）（11:27）</li><li>对称加密 vs 非对称加密 vs 混合加密</li><li>TLS/SSL 握手过程详解</li><li>证书链验证机制</li></ul><h4 id="_2-2-http-状态码" tabindex="-1">2.2 HTTP 状态码 <a class="header-anchor" href="#_2-2-http-状态码" aria-label="Permalink to “2.2 HTTP 状态码”">​</a></h4><ul><li>HTTP 状态码告诉我们哪个环节出了问题？</li><li>2xx / 3xx / 4xx / 5xx 在爬虫中的含义</li><li>301/302 重定向处理</li><li>403 Forbidden / 429 Too Many Requests 的反爬含义</li></ul><h4 id="_2-3-http-请求头与反爬" tabindex="-1">2.3 HTTP 请求头与反爬 <a class="header-anchor" href="#_2-3-http-请求头与反爬" aria-label="Permalink to “2.3 HTTP 请求头与反爬”">​</a></h4><ul><li>这些 HTTP 请求头信息出卖了爬虫？（上）（13:00）</li><li>这些 HTTP 请求头信息出卖了爬虫？（下）（11:50）</li><li>User-Agent 指纹识别与伪装</li><li>Referer 来源验证</li><li>Accept-Language / Accept-Encoding 特征分析</li><li>X-Requested-With 与 AJAX 请求识别</li></ul><h4 id="_2-4-http-协议演进" tabindex="-1">2.4 HTTP 协议演进 <a class="header-anchor" href="#_2-4-http-协议演进" aria-label="Permalink to “2.4 HTTP 协议演进”">​</a></h4><ul><li>每次 HTTP 协议升级分别解决什么问题？</li><li>HTTP/1.0 → HTTP/1.1 → HTTP/2 → HTTP/3 演进</li><li>HTTP/2 多路复用对爬虫的影响</li></ul><h4 id="_2-5-https-证书认证" tabindex="-1">2.5 HTTPS 证书认证 <a class="header-anchor" href="#_2-5-https-证书认证" aria-label="Permalink to “2.5 HTTPS 证书认证”">​</a></h4><ul><li>爬虫如何解决 HTTPS 证书认证？（13:16）</li><li>证书信息的补充（03:29）</li><li><code>verify=False</code> 的风险与替代方案</li><li>自签名证书处理</li></ul><h3 id="本章知识点-1" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点-1" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>HTTPS 加密原理（TLS 握手、证书链）</li><li>HTTP 状态码体系与爬虫调试</li><li>请求头反爬识别与伪装</li><li>HTTP 协议版本差异</li><li>SSL 证书处理方案</li></ul><hr><h2 id="第三章-手把手教你搭建代理服务" tabindex="-1">第三章：手把手教你搭建代理服务 <a class="header-anchor" href="#第三章-手把手教你搭建代理服务" aria-label="Permalink to “第三章：手把手教你搭建代理服务”">​</a></h2><h3 id="教学目标-2" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-2" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>了解主流代理 IP 服务商的优劣与选型</li><li>掌握 Squid 自建代理服务的完整流程</li><li>实现代理服务的加密认证</li><li>构建可维护的代理池技术方案</li></ol><h3 id="学习痛点-2" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-2" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>代理 IP 服务商太多，不知道怎么选</li><li>只会用第三方代理 API，不会自建代理服务</li><li>代理服务没有加密，容易被探测和封禁</li><li>代理池管理混乱，不知道怎么系统化搭建</li></ul><h3 id="章节内容-2" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容-2" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_3-1-代理-ip-服务商对比" tabindex="-1">3.1 代理 IP 服务商对比 <a class="header-anchor" href="#_3-1-代理-ip-服务商对比" aria-label="Permalink to “3.1 代理 IP 服务商对比”">​</a></h4><ul><li>纵向对比各大代理 IP 服务商的优劣（1）（08:54）</li><li>纵向对比各大代理 IP 服务商的优劣（2）（14:49）</li><li>纵向对比各大代理 IP 服务商的优劣（3）（10:44）</li><li>短效代理 vs 长效代理的适用场景</li><li>代理 IP 类型：透明代理 / 匿名代理 / 高匿代理</li></ul><h4 id="_3-2-squid-自建代理服务" tabindex="-1">3.2 Squid 自建代理服务 <a class="header-anchor" href="#_3-2-squid-自建代理服务" aria-label="Permalink to “3.2 Squid 自建代理服务”">​</a></h4><ul><li>用 Squid 自建代理服务（1）（12:56）</li><li>用 Squid 自建代理服务（2）（13:58）</li><li>创建加密的 Squid 代理服务（3）（22:19）</li><li>Squid 配置文件详解</li><li>认证方案：basic_auth / digest_auth</li></ul><h4 id="_3-3-代理池技术方案" tabindex="-1">3.3 代理池技术方案 <a class="header-anchor" href="#_3-3-代理池技术方案" aria-label="Permalink to “3.3 代理池技术方案”">​</a></h4><ul><li>Squid + VPS 搭建代理池的技术方案</li><li>代理池架构设计：获取 → 验证 → 存储 → 调度</li><li>代理可用性检测与自动剔除</li><li>代理轮换策略</li></ul><h4 id="_3-4-第三方代理产品应用" tabindex="-1">3.4 第三方代理产品应用 <a class="header-anchor" href="#_3-4-第三方代理产品应用" aria-label="Permalink to “3.4 第三方代理产品应用”">​</a></h4><ul><li>一起分析第三方代理产品的应用场景（17:07）</li><li>第三方代理 API 的接入与封装</li><li>自建代理 vs 第三方代理的成本分析</li></ul><h3 id="本章实战项目" tabindex="-1">本章实战项目 <a class="header-anchor" href="#本章实战项目" aria-label="Permalink to “本章实战项目”">​</a></h3><p><strong>项目名称</strong>：Squid + VPS 搭建加密代理池</p><p><strong>项目内容</strong>：</p><ol><li>在 VPS 上部署 Squid 代理服务</li><li>配置代理认证（用户名/密码）</li><li>搭建多节点代理池</li><li>实现代理可用性检测与自动轮换</li><li>封装 Python 代理调用接口</li></ol><h3 id="本章知识点-2" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点-2" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>主流代理 IP 服务商对比与选型</li><li>Squid 代理服务搭建与加密认证</li><li>代理池架构设计与管理</li><li>代理轮换策略与可用性检测</li></ul><hr><h2 id="第四章-破解加密登录的过程" tabindex="-1">第四章：破解加密登录的过程 <a class="header-anchor" href="#第四章-破解加密登录的过程" aria-label="Permalink to “第四章：破解加密登录的过程”">​</a></h2><h3 id="教学目标-3" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-3" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>理解明文传输与密文传输的区别</li><li>掌握账号信息加密的通用算法</li><li>掌握通过抓包逆向分析 JS 代码的完整流程</li><li>突破无限 Debugger 反调试机制</li><li>使用 BreakPoint 调试 JS 堆栈</li><li>掌握 JS 篡改与伪装技术（ReRes）</li><li>用 Python 逆向重构加密函数</li><li>用 Python 调度 JS 文件实现密码加密</li></ol><h3 id="学习痛点-3" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-3" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>遇到加密登录直接放弃，不知道怎么逆向</li><li>无限 Debugger 卡死浏览器，无法调试</li><li>JS 逆向分析毫无头绪，不知道从哪里入手</li><li>逆向出来了但不会用 Python 重构加密逻辑</li></ul><h3 id="章节内容-3" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容-3" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_4-1-加密基础" tabindex="-1">4.1 加密基础 <a class="header-anchor" href="#_4-1-加密基础" aria-label="Permalink to “4.1 加密基础”">​</a></h4><ul><li>明文传输和密文传输</li><li>了解账号信息加密的通用算法</li><li>常见加密算法：MD5 / SHA / AES / DES / RSA</li><li>Base64 编码 vs 加密</li></ul><h4 id="_4-2-抓包逆向分析-js-代码" tabindex="-1">4.2 抓包逆向分析 JS 代码 <a class="header-anchor" href="#_4-2-抓包逆向分析-js-代码" aria-label="Permalink to “4.2 抓包逆向分析 JS 代码”">​</a></h4><ul><li>通过抓包逆向分析 JS 代码（1）（11:26）</li><li>通过抓包逆向分析 JS 代码（2）（12:47）</li><li>通过抓包逆向分析 JS 代码（3）（20:35）</li><li>Chrome 开发者工具一览</li><li>开发者工具栏的网络栏使用说明（01:33）</li><li>抓包工具对比：Chrome DevTools vs Fiddler vs Charles vs mitmproxy</li></ul><h4 id="_4-3-突破无限-debugger" tabindex="-1">4.3 突破无限 Debugger <a class="header-anchor" href="#_4-3-突破无限-debugger" aria-label="Permalink to “4.3 突破无限 Debugger”">​</a></h4><ul><li>无限 Debugger 产生的原因和突破方法（23:16）</li><li><code>debugger</code> 语句的反调试原理</li><li>条件断点禁用 Debugger</li><li>函数重写覆盖 Debugger</li><li>远程加载 JS 文件的篡改</li></ul><h4 id="_4-4-js-断点调试与堆栈分析" tabindex="-1">4.4 JS 断点调试与堆栈分析 <a class="header-anchor" href="#_4-4-js-断点调试与堆栈分析" aria-label="Permalink to “4.4 JS 断点调试与堆栈分析”">​</a></h4><ul><li>添加 BreakPoint 调试 JS 堆栈内容（上）（20:22）</li><li>添加 BreakPoint 调试 JS 堆栈内容（下）（22:38）</li><li>断点类型：行断点 / 条件断点 / DOM 断点 / XHR 断点</li><li>Call Stack 调用栈分析</li><li>Scope 作用域与变量查看</li><li>Watch 表达式与逐步执行</li></ul><h4 id="_4-5-js-篡改与伪装" tabindex="-1">4.5 JS 篡改与伪装 <a class="header-anchor" href="#_4-5-js-篡改与伪装" aria-label="Permalink to “4.5 JS 篡改与伪装”">​</a></h4><ul><li>适用 ReRes 篡改和伪装 JS 内容（30:30）</li><li>ReRes 插件工作原理：URL 重定向到本地文件</li><li>本地 JS 修改后替换线上 JS</li><li>Tampermonkey 油猴脚本替代方案</li><li>Charles / Fiddler Map Local 方案</li></ul><h4 id="_4-6-python-逆向重构加密函数" tabindex="-1">4.6 Python 逆向重构加密函数 <a class="header-anchor" href="#_4-6-python-逆向重构加密函数" aria-label="Permalink to “4.6 Python 逆向重构加密函数”">​</a></h4><ul><li>Python 逆向重构加密函数（上）（19:43）</li><li>Python 逆向重构加密函数（下）（23:15）</li><li>JS → Python 代码翻译技巧</li><li>常见 JS 加密库的 Python 对应实现</li><li>边界 case 处理与结果验证</li></ul><h4 id="_4-7-python-调度-js-文件" tabindex="-1">4.7 Python 调度 JS 文件 <a class="header-anchor" href="#_4-7-python-调度-js-文件" aria-label="Permalink to “4.7 Python 调度 JS 文件”">​</a></h4><ul><li>Python 调度 JS 文件实现密码加密（上）（12:07）</li><li>Python 调度 JS 文件实现密码加密（下）（15:48）</li><li><code>execjs</code> 库：直接执行 JS 代码</li><li><code>PyExecJS</code> vs <code>execjs</code> vs <code>Node.js subprocess</code> 对比</li><li>JS 环境补全：window / document / navigator 对象模拟</li><li>性能与稳定性优化</li></ul><h3 id="本章实战项目-1" tabindex="-1">本章实战项目 <a class="header-anchor" href="#本章实战项目-1" aria-label="Permalink to “本章实战项目”">​</a></h3><p><strong>项目名称</strong>：逆向破解真实网站加密登录</p><p><strong>项目内容</strong>：</p><ol><li>抓包分析目标网站登录请求</li><li>定位 JS 加密函数</li><li>突破无限 Debugger 反调试</li><li>断点调试分析加密逻辑</li><li>用 ReRes 篡改 JS 验证分析结果</li><li>Python 逆向重构加密函数</li><li>Python 调度 JS 文件实现加密登录</li><li>两种方案对比与选型</li></ol><h3 id="本章知识点-3" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点-3" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>加密算法基础（MD5/SHA/AES/DES/RSA）</li><li>Chrome DevTools 逆向分析</li><li>无限 Debugger 反调试突破</li><li>JS 断点调试与堆栈分析</li><li>ReRes / Tampermonkey JS 篡改</li><li>Python 逆向重构加密逻辑</li><li><code>execjs</code> / <code>PyExecJS</code> 调度 JS 执行</li></ul><hr><h2 id="第五章-cookie-池的搭建和维护" tabindex="-1">第五章：Cookie 池的搭建和维护 <a class="header-anchor" href="#第五章-cookie-池的搭建和维护" aria-label="Permalink to “第五章：Cookie 池的搭建和维护”">​</a></h2><h3 id="教学目标-4" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-4" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>理解 Cookie 的来源、重要性与使用场景</li><li>掌握 Cookie 的属性与时效管理</li><li>区分 Session 与 Cookie 的关系</li><li>用 Python 实现 Cookie 持久化与复用</li><li>实现 Cookie 的协助式提取</li><li>搭建 Cookie 池管理系统</li><li>高并发维护上万 Cookie 的有效性</li></ol><h3 id="学习痛点-4" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-4" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>单账号抓取数据量太少，多账号管理混乱</li><li>Cookie 过期后不知道怎么自动刷新</li><li>上万 Cookie 的有效性维护没有头绪</li><li>Cookie 调试环境搭建耗时，每次都要手动操作</li></ul><h3 id="章节内容-4" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容-4" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_5-1-cookie-基础" tabindex="-1">5.1 Cookie 基础 <a class="header-anchor" href="#_5-1-cookie-基础" aria-label="Permalink to “5.1 Cookie 基础”">​</a></h4><ul><li>Cookie 的来源和重要性</li><li>Cookie 池的使用场景（14:02）</li><li>Cookie 的属性和时效说明（20:02） <ul><li>Name / Value / Domain / Path / Expires / Max-Age</li><li>Secure / HttpOnly / SameSite</li></ul></li><li>Session 和 Cookie 的共同点和区别（16:36）</li></ul><h4 id="_5-2-cookie-持久化与复用" tabindex="-1">5.2 Cookie 持久化与复用 <a class="header-anchor" href="#_5-2-cookie-持久化与复用" aria-label="Permalink to “5.2 Cookie 持久化与复用”">​</a></h4><ul><li>用 Python 对 Cookie 进行持久化和装载复用（1）（21:04）</li><li>用 Python 对 Cookie 进行持久化和装载复用（2）（14:57）</li><li><code>http.cookiejar</code> 标准库</li><li><code>requests.Session</code> 的 Cookie 管理</li><li>Cookie 序列化存储：JSON / Pickle / SQLite</li></ul><h4 id="_5-3-cookie-协助式提取" tabindex="-1">5.3 Cookie 协助式提取 <a class="header-anchor" href="#_5-3-cookie-协助式提取" aria-label="Permalink to “5.3 Cookie 协助式提取”">​</a></h4><ul><li>用 Python 实现 Cookie 的协助式提取和复用（1）（16:49）</li><li>用 Python 实现 Cookie 的协助式提取和复用（2）（16:35）</li><li>用 Python 实现 Cookie 的协助式提取和复用（3）（22:33）</li><li>Selenium / Playwright 提取 Cookie</li><li>浏览器 Cookie 导出插件</li><li>协助式提取：半自动 + 全自动方案</li></ul><h4 id="_5-4-cookie-池管理系统" tabindex="-1">5.4 Cookie 池管理系统 <a class="header-anchor" href="#_5-4-cookie-池管理系统" aria-label="Permalink to “5.4 Cookie 池管理系统”">​</a></h4><ul><li>Cookie 的维护方案和管理系统</li><li>Cookie 池架构设计： <ul><li>存储层：Redis / MySQL</li><li>管理层：增删改查 / 分组 / 优先级</li><li>调度层：轮询 / 随机 / 加权</li><li>验证层：有效性检测 / 自动剔除 / 自动补充</li></ul></li></ul><h4 id="_5-5-cookie-调试环境" tabindex="-1">5.5 Cookie 调试环境 <a class="header-anchor" href="#_5-5-cookie-调试环境" aria-label="Permalink to “5.5 Cookie 调试环境”">​</a></h4><ul><li>一键部署大批量的 Cookie 调试环境（上）（20:25）</li><li>一键部署大批量的 Cookie 调试环境（下）（26:54）</li><li>复杂登录过程的 Cookie 调试环境 - 上（25:00）</li><li>复杂登录过程的 Cookie 调试环境 - 下（09:50）</li><li>Chrome 多 Profile 隔离登录</li><li>Cookie 批量导入导出工具</li></ul><h4 id="_5-6-cookie-池实战" tabindex="-1">5.6 Cookie 池实战 <a class="header-anchor" href="#_5-6-cookie-池实战" aria-label="Permalink to “5.6 Cookie 池实战”">​</a></h4><ul><li>【社交平台实战】提取 Cookie 保存到 Cookie 池中（16:37）</li><li>【Cookie 实战】高并发维护上万 Cookie 的有效性（上）（14:48）</li><li>【Cookie 实战】高并发维护上万 Cookie 的有效性（下）（29:59）</li><li>高并发验证方案：<code>asyncio</code> + <code>aiohttp</code> 批量检测</li><li>失效 Cookie 自动标记与替换</li><li>Cookie 生命周期管理：创建 → 使用 → 验证 → 失效 → 替换</li></ul><h3 id="本章实战项目-2" tabindex="-1">本章实战项目 <a class="header-anchor" href="#本章实战项目-2" aria-label="Permalink to “本章实战项目”">​</a></h3><p><strong>项目名称</strong>：高并发 Cookie 池管理系统</p><p><strong>项目内容</strong>：</p><ol><li>设计 Cookie 池存储架构（Redis）</li><li>实现 Cookie 持久化与自动装载</li><li>实现 Cookie 协助式提取工具</li><li>搭建 Cookie 调试环境（多 Chrome Profile）</li><li>实现高并发 Cookie 有效性检测（<code>asyncio</code> + <code>aiohttp</code>）</li><li>实现 Cookie 自动补充与淘汰机制</li><li>支持社交平台 Cookie 批量提取入池</li><li>管理 10000+ Cookie 的并发调度</li></ol><h3 id="本章知识点-4" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点-4" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>Cookie 属性与时效管理</li><li>Session vs Cookie</li><li>Cookie 持久化方案（<code>cookiejar</code> / <code>requests.Session</code>）</li><li>Cookie 协助式提取（Selenium / 浏览器插件）</li><li>Cookie 池架构设计（存储 / 管理 / 调度 / 验证）</li><li>高并发 Cookie 有效性维护</li><li>Chrome 多 Profile 隔离</li></ul><hr><h2 id="第六章-调度浏览器降低分析难度" tabindex="-1">第六章：调度浏览器降低分析难度 <a class="header-anchor" href="#第六章-调度浏览器降低分析难度" aria-label="Permalink to “第六章：调度浏览器降低分析难度”">​</a></h2><h3 id="教学目标-5" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-5" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>对比 Selenium / PhantomJS / Puppeteer 的优劣与选型</li><li>掌握 Selenium 的核心操作与 Chrome 远程调试</li><li>掌握 Puppeteer 的工作原理与应用场景</li><li>实现浏览器登录官网自动化</li><li>实现滑动验证码全自动识别</li><li>掌握图像对比算法（RGB / Rembrandt / SSIM）</li><li>用贝塞尔曲线模拟真人滑动行为</li></ol><h3 id="学习痛点-5" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-5" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>纯请求方式被反爬封死，不知道怎么用浏览器降维打击</li><li>Selenium 速度慢、容易被检测，不知道怎么优化</li><li>滑动验证码过不去，不知道怎么识别和模拟</li><li>滑动轨迹太机械，被识别为机器人</li></ul><h3 id="章节内容-5" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容-5" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_6-1-浏览器自动化工具对比" tabindex="-1">6.1 浏览器自动化工具对比 <a class="header-anchor" href="#_6-1-浏览器自动化工具对比" aria-label="Permalink to “6.1 浏览器自动化工具对比”">​</a></h4><ul><li>对比 Selenium / PhantomJS / Puppeteer</li><li>各工具优劣势： <ul><li>Selenium：生态成熟、多语言支持、速度慢</li><li>PhantomJS：已废弃、不推荐</li><li>Puppeteer：Node.js 生态、API 现代、性能好</li><li>Playwright：新一代标准（补充）</li></ul></li><li>选型建议与适用场景</li></ul><h4 id="_6-2-selenium-实战" tabindex="-1">6.2 Selenium 实战 <a class="header-anchor" href="#_6-2-selenium-实战" aria-label="Permalink to “6.2 Selenium 实战”">​</a></h4><ul><li>Selenium 的优势和点击操作（上）（13:28）</li><li>Selenium 的优势和点击操作（下）（17:09）</li><li>元素定位策略：ID / Class / XPath / CSS Selector</li><li>显式等待 vs 隐式等待</li><li><code>WebDriverWait</code> + <code>expected_conditions</code></li><li>Selenium 反检测：<code>undetected-chromedriver</code></li></ul><h4 id="_6-3-chrome-远程调试" tabindex="-1">6.3 Chrome 远程调试 <a class="header-anchor" href="#_6-3-chrome-远程调试" aria-label="Permalink to “6.3 Chrome 远程调试”">​</a></h4><ul><li>Chrome 的远程调试能力（18:09）</li><li>Chrome 开启远程调试端口</li><li><code>--remote-debugging-port</code> 参数配置</li><li>远程调试协议（CDP）基础</li><li>通过 Chrome 隔离实现一台电脑登录多个账号（上）（13:08）</li><li>通过 Chrome 隔离实现一台电脑登录多个账号（下）（23:14）</li><li>Chrome <code>--user-data-dir</code> 多实例隔离</li></ul><h4 id="_6-4-puppeteer-实战" tabindex="-1">6.4 Puppeteer 实战 <a class="header-anchor" href="#_6-4-puppeteer-实战" aria-label="Permalink to “6.4 Puppeteer 实战”">​</a></h4><ul><li>Puppeteer 的工作原理及应用场景</li><li>Node.js + Puppeteer 实现登录官网（上）（14:50）</li><li>Node.js + Puppeteer 实现登录官网（下）（21:51）</li><li>Puppeteer API 核心：<code>page.goto()</code> / <code>page.click()</code> / <code>page.evaluate()</code></li><li><code>puppeteer.connect()</code> 连接已有 Chrome 实例</li><li>Headless vs Headful 模式</li></ul><h4 id="_6-5-滑动验证码识别" tabindex="-1">6.5 滑动验证码识别 <a class="header-anchor" href="#_6-5-滑动验证码识别" aria-label="Permalink to “6.5 滑动验证码识别”">​</a></h4><ul><li>Node.js + Puppeteer 实现滑动验证码全自动识别（上）（20:19）</li><li>Node.js + Puppeteer 实现滑动验证码全自动识别（下）（25:10）</li><li>滑动验证码原理：缺口位置识别 + 轨迹模拟</li><li>截图与图像处理：获取验证码图片</li><li>缺口位置定位算法</li></ul><h4 id="_6-6-图像对比算法" tabindex="-1">6.6 图像对比算法 <a class="header-anchor" href="#_6-6-图像对比算法" aria-label="Permalink to “6.6 图像对比算法”">​</a></h4><ul><li>网站登录项目架构说明（上）（16:34）</li><li>网站登录项目架构说明（中）（17:08）</li><li>网站登录项目架构说明（下）（15:20）</li><li><strong>像素 RGB 对比算法</strong>（上）（15:52）</li><li><strong>像素 RGB 对比算法</strong>（下）（18:44） <ul><li>逐像素比对、差异阈值、二值化</li></ul></li><li><strong>Rembrandt 算法</strong>（18:48） <ul><li>图像相似度比较库</li></ul></li><li><strong>SSIM 结构相似性算法</strong>（14:55） <ul><li>结构相似性指数原理</li><li>亮度 / 对比度 / 结构三维度比较</li></ul></li><li>三种算法对比与适用场景</li></ul><h4 id="_6-7-真人滑动模拟" tabindex="-1">6.7 真人滑动模拟 <a class="header-anchor" href="#_6-7-真人滑动模拟" aria-label="Permalink to “6.7 真人滑动模拟”">​</a></h4><ul><li>利用贝塞尔曲线模拟真人滑动鼠标（27:17）</li><li>贝塞尔曲线（Bézier Curve）数学原理</li><li>轨迹生成：起点 → 控制点 → 终点</li><li>速度曲线：先快后慢 / 先慢后快 / 匀速 + 随机抖动</li><li>鼠标事件序列：mousedown → mousemove × N → mouseup</li><li>反检测：人类行为特征模拟</li></ul><h3 id="本章实战项目-3" tabindex="-1">本章实战项目 <a class="header-anchor" href="#本章实战项目-3" aria-label="Permalink to “本章实战项目”">​</a></h3><p><strong>项目名称</strong>：Puppeteer 自动登录 + 滑动验证码识别系统</p><p><strong>项目内容</strong>：</p><ol><li>搭建 Node.js + Puppeteer 项目架构</li><li>实现网站自动登录流程</li><li>实现滑动验证码截图与缺口定位</li><li>实现三种图像对比算法（RGB / Rembrandt / SSIM）</li><li>用贝塞尔曲线生成真人滑动轨迹</li><li>验证码通过率测试与优化</li><li>支持多网站适配</li></ol><h3 id="本章知识点-5" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点-5" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>浏览器自动化工具选型（Selenium / Puppeteer / Playwright）</li><li>Selenium 核心操作与反检测</li><li>Chrome 远程调试（CDP 协议）</li><li>Chrome 多实例隔离</li><li>Puppeteer API 与项目架构</li><li>滑动验证码识别全流程</li><li>图像对比算法（RGB / Rembrandt / SSIM）</li><li>贝塞尔曲线轨迹模拟与真人行为仿真</li></ul><hr><h2 id="第七章-逆向破解被加密的数据" tabindex="-1">第七章：逆向破解被加密的数据 <a class="header-anchor" href="#第七章-逆向破解被加密的数据" aria-label="Permalink to “第七章：逆向破解被加密的数据”">​</a></h2><h3 id="教学目标-6" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-6" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>理解字体渲染的完整流程</li><li>掌握字体文件检查与数据查看方法</li><li>实现字体文件转换与网页内容还原</li><li>掌握 Base64 编码在网页中的应用与解码</li><li>实现上百页加密数据的完美还原</li></ol><h3 id="学习痛点-6" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-6" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>网页上的数据看起来正常但复制出来是乱码</li><li>不理解字体加密原理，遇到就绕道</li><li>Base64 编码的数据不知道怎么识别和解码</li><li>数据加密贯穿上百页，不知道怎么批量还原</li></ul><h3 id="章节内容-6" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容-6" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_7-1-字体渲染原理" tabindex="-1">7.1 字体渲染原理 <a class="header-anchor" href="#_7-1-字体渲染原理" aria-label="Permalink to “7.1 字体渲染原理”">​</a></h4><ul><li>字体渲染的顺序和原理</li><li>全方位了解字体渲染的全过程（13:11）</li><li>浏览器渲染流水线：HTML → DOM → CSSOM → Render Tree → Layout → Paint</li><li><code>@font-face</code> 自定义字体加载</li><li>字符编码 → 字形（Glyph）映射机制</li><li>字体加密反爬原理：自定义字形替换 Unicode 映射</li></ul><h4 id="_7-2-字体文件检查与查看" tabindex="-1">7.2 字体文件检查与查看 <a class="header-anchor" href="#_7-2-字体文件检查与查看" aria-label="Permalink to “7.2 字体文件检查与查看”">​</a></h4><ul><li>字体文件的检查和数据查看（19:06）</li><li>字体文件格式：WOFF / WOFF2 / TTF / OTF</li><li>字体编辑工具：FontForge / FontCreator</li><li>XML 格式查看字体内部映射关系</li><li>cmap 表分析：Unicode → Glyph ID 映射</li><li>在线字体查看工具</li></ul><h4 id="_7-3-字体文件转换与内容还原" tabindex="-1">7.3 字体文件转换与内容还原 <a class="header-anchor" href="#_7-3-字体文件转换与内容还原" aria-label="Permalink to “7.3 字体文件转换与内容还原”">​</a></h4><ul><li>字体文件转换并实现网页内容还原（24:50）</li><li>字体文件格式转换（WOFF → TTF）</li><li>解析字体 cmap 表获取真实映射关系</li><li>构建映射字典：加密字符 → 真实字符</li><li>批量替换网页中的加密字符</li><li>处理动态字体文件（每次请求字体映射不同）</li></ul><h4 id="_7-4-base64-数据解码" tabindex="-1">7.4 Base64 数据解码 <a class="header-anchor" href="#_7-4-base64-数据解码" aria-label="Permalink to “7.4 Base64 数据解码”">​</a></h4><ul><li>解析出给出 Base64 字符串的原数据（作业题）</li><li>Base64 在网页中的常见应用场景（讨论题）</li><li>Base64 编码原理：3 字节 → 4 字符</li><li>图片 Base64 内联（data URI scheme）</li><li>API 响应中 Base64 编码的 JSON 数据</li><li>Python <code>base64</code> 标准库使用</li></ul><h4 id="_7-5-批量数据还原实战" tabindex="-1">7.5 批量数据还原实战 <a class="header-anchor" href="#_7-5-批量数据还原实战" aria-label="Permalink to “7.5 批量数据还原实战”">​</a></h4><ul><li>完美还原上百页的数据内容（上）（12:33）</li><li>完美还原上百页的数据内容（下）（17:58）</li><li>分页抓取 + 字体解密流水线</li><li>动态字体映射的自动化处理</li><li>数据完整性验证</li></ul><h3 id="本章实战项目-4" tabindex="-1">本章实战项目 <a class="header-anchor" href="#本章实战项目-4" aria-label="Permalink to “本章实战项目”">​</a></h3><p><strong>项目名称</strong>：字体加密破解与批量数据还原</p><p><strong>项目内容</strong>：</p><ol><li>分析目标网站字体加密机制</li><li>下载并解析字体文件（WOFF/TTF）</li><li>构建字符映射字典</li><li>处理动态字体文件（每次请求映射不同）</li><li>实现批量分页抓取 + 实时解密</li><li>上百页数据完美还原</li><li>数据完整性校验</li></ol><h3 id="本章知识点-6" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点-6" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>浏览器字体渲染全流程</li><li><code>@font-face</code> 与字体加密反爬原理</li><li>字体文件格式（WOFF/WOFF2/TTF）</li><li>字体 cmap 表解析与映射关系构建</li><li>动态字体文件处理</li><li>Base64 编码原理与解码</li><li>批量数据解密流水线设计</li></ul><hr><h2 id="第八章-反爬的实战练习" tabindex="-1">第八章：反爬的实战练习 <a class="header-anchor" href="#第八章-反爬的实战练习" aria-label="Permalink to “第八章：反爬的实战练习”">​</a></h2><h3 id="教学目标-7" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-7" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>综合运用前述章节知识进行反爬实战</li><li>掌握爬虫文件的解析与数据抓取</li><li>分析并突破网站反爬措施</li><li>Scrapy 框架接入 Cookie 池管理系统</li><li>掌握分布式爬虫的架设</li></ol><h3 id="学习痛点-7" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-7" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>学了很多零散知识，但缺乏综合实战经验</li><li>Scrapy 框架接入 Cookie 池不知道怎么整合</li><li>分布式爬虫只在概念层面，没有实际搭建过</li></ul><h3 id="章节内容-7" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容-7" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_8-1-实战目标说明" tabindex="-1">8.1 实战目标说明 <a class="header-anchor" href="#_8-1-实战目标说明" aria-label="Permalink to “8.1 实战目标说明”">​</a></h4><ul><li>目标网站和数据抓取要求说明</li><li>爬虫文件的解析和数据的抓取（上）（17:36）</li><li>爬虫文件的解析和数据的抓取（下）（15:59）</li><li>目标网站结构分析</li><li>数据字段定义与抓取策略</li></ul><h4 id="_8-2-反爬分析与突破" tabindex="-1">8.2 反爬分析与突破 <a class="header-anchor" href="#_8-2-反爬分析与突破" aria-label="Permalink to “8.2 反爬分析与突破”">​</a></h4><ul><li>反爬措施的分析和突破（18:08）</li><li>综合反爬手段识别：请求头检测 / IP 限制 / 登录态验证 / 数据加密</li><li>针对性突破方案设计</li><li>突破效果验证</li></ul><h4 id="_8-3-scrapy-接入-cookie-池" tabindex="-1">8.3 Scrapy 接入 Cookie 池 <a class="header-anchor" href="#_8-3-scrapy-接入-cookie-池" aria-label="Permalink to “8.3 Scrapy 接入 Cookie 池”">​</a></h4><ul><li>Scrapy 接入 Cookie 池管理系统（上）（18:34）</li><li>Scrapy 接入 Cookie 池管理系统（中）（18:56）</li><li>Scrapy 接入 Cookie 池管理系统（下）（17:21）</li><li>Scrapy 架构回顾：Engine / Spider / Downloader / Pipeline</li><li>Downloader Middleware 中间件接入 Cookie 池</li><li>Cookie 轮换策略：每个请求分配不同 Cookie</li><li>Cookie 失效自动标记与替换</li><li>集成代理池 + Cookie 池双重反反爬</li></ul><h4 id="_8-4-分布式爬虫架设" tabindex="-1">8.4 分布式爬虫架设 <a class="header-anchor" href="#_8-4-分布式爬虫架设" aria-label="Permalink to “8.4 分布式爬虫架设”">​</a></h4><ul><li>分布式爬虫的架设（上）（15:26）</li><li>分布式爬虫的架设（中）（16:34）</li><li>分布式爬虫的架设（下）（15:10）</li><li>Scrapy-Redis 分布式方案 <ul><li>Redis 作为请求队列与去重集合</li><li>分布式 Spider 调度</li><li>多节点 Worker 部署</li></ul></li><li>Scrapyd 部署与管理 <ul><li>Scrapyd 服务部署</li><li><code>scrapyd-client</code> 打包上传</li><li>Scrapyd API 远程管理</li></ul></li><li>分布式爬虫管理系统：Gerapy / Crawlab</li></ul><h3 id="本章实战项目-5" tabindex="-1">本章实战项目 <a class="header-anchor" href="#本章实战项目-5" aria-label="Permalink to “本章实战项目”">​</a></h3><p><strong>项目名称</strong>：Scrapy + Cookie 池 + 分布式爬虫综合实战</p><p><strong>项目内容</strong>：</p><ol><li>分析目标网站反爬措施</li><li>编写 Spider 解析规则与数据抓取</li><li>开发 Downloader Middleware 接入 Cookie 池</li><li>实现代理池 + Cookie 池双重反反爬</li><li>基于 Scrapy-Redis 搭建分布式爬虫</li><li>Scrapyd 部署与远程管理</li><li>多节点 Worker 分布式抓取</li></ol><h3 id="本章知识点-7" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点-7" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>爬虫项目实战全流程</li><li>反爬措施综合分析与突破</li><li>Scrapy 框架架构与 Middleware 开发</li><li>Scrapy-Redis 分布式方案</li><li>Scrapyd 部署与管理</li><li>分布式爬虫管理系统（Gerapy / Crawlab）</li></ul><hr><h2 id="第九章-分布式爬虫架构方案" tabindex="-1">第九章：分布式爬虫架构方案 <a class="header-anchor" href="#第九章-分布式爬虫架构方案" aria-label="Permalink to “第九章：分布式爬虫架构方案”">​</a></h2><h3 id="教学目标-8" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-8" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>理解分布式爬虫的优势与必要性</li><li>掌握下游业务如何使用爬取到的数据</li><li>掌握数据和文件的存储方案</li><li>掌握大数据存储架构选型</li></ol><h3 id="学习痛点-8" tabindex="-1">学习痛点 <a class="header-anchor" href="#学习痛点-8" aria-label="Permalink to “学习痛点”">​</a></h3><ul><li>爬了海量数据但不知道怎么存储和下游消费</li><li>文件存储（图片/视频/PDF）没有系统方案</li><li>大数据场景下 MySQL 扛不住，不知道该用什么</li></ul><h3 id="章节内容-8" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容-8" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_9-1-分布式爬虫架构" tabindex="-1">9.1 分布式爬虫架构 <a class="header-anchor" href="#_9-1-分布式爬虫架构" aria-label="Permalink to “9.1 分布式爬虫架构”">​</a></h4><ul><li>分布式爬虫的优势和必要性</li><li>分布式爬虫架构方案讨论</li><li>主从架构 vs 对等架构</li><li>任务调度与负载均衡</li><li>容错与故障恢复</li></ul><h4 id="_9-2-下游数据消费" tabindex="-1">9.2 下游数据消费 <a class="header-anchor" href="#_9-2-下游数据消费" aria-label="Permalink to “9.2 下游数据消费”">​</a></h4><ul><li>下游业务如何使用爬取到的数据（17:13）</li><li>数据清洗与结构化</li><li>数据推送：API / 消息队列 / 数据库直写</li><li>数据格式标准化</li></ul><h4 id="_9-3-存储方案" tabindex="-1">9.3 存储方案 <a class="header-anchor" href="#_9-3-存储方案" aria-label="Permalink to “9.3 存储方案”">​</a></h4><ul><li>数据和文件的存储方案（14:22）</li><li><strong>结构化数据存储</strong>： <ul><li>MySQL / PostgreSQL：关系型存储</li><li>MongoDB：文档型存储，适合非结构化数据</li><li>Elasticsearch：全文检索与数据分析</li></ul></li><li><strong>文件存储</strong>： <ul><li>本地文件系统 + NFS</li><li>对象存储：MinIO / OSS / S3</li><li>分布式文件系统：HDFS</li></ul></li><li><strong>大数据存储</strong>： <ul><li>HBase：列式存储，亿级数据毫秒查询</li><li>Hive：数据仓库，离线分析</li><li>ClickHouse：OLAP 实时分析</li><li>Spark：大数据计算框架</li></ul></li></ul><h3 id="本章实战项目-6" tabindex="-1">本章实战项目 <a class="header-anchor" href="#本章实战项目-6" aria-label="Permalink to “本章实战项目”">​</a></h3><p><strong>项目名称</strong>：分布式爬虫数据存储与消费方案</p><p><strong>项目内容</strong>：</p><ol><li>设计分布式爬虫整体架构</li><li>实现结构化数据入 MySQL / MongoDB</li><li>实现文件上传到对象存储（MinIO / OSS）</li><li>实现数据推送至下游业务（API + 消息队列）</li><li>大数据场景下 HBase / Hive 存储方案</li><li>Spark 数据清洗与分析</li></ol><h3 id="本章知识点-8" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点-8" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>分布式爬虫架构设计（主从 / 对等）</li><li>下游数据消费方案（API / MQ / DB）</li><li>结构化数据存储选型（MySQL / MongoDB / ES）</li><li>文件存储方案（本地 / 对象存储 / HDFS）</li><li>大数据存储（HBase / Hive / ClickHouse / Spark）</li></ul><hr><h2 id="第十章-课程终极测验" tabindex="-1">第十章：课程终极测验 <a class="header-anchor" href="#第十章-课程终极测验" aria-label="Permalink to “第十章：课程终极测验”">​</a></h2><h3 id="教学目标-9" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-9" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>巩固前述所有章节的核心知识点</li><li>通过 30 道测验题查漏补缺</li><li>检验学习效果</li></ol><h3 id="章节内容-9" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容-9" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_10-1-http-基础" tabindex="-1">10.1 HTTP 基础 <a class="header-anchor" href="#_10-1-http-基础" aria-label="Permalink to “10.1 HTTP 基础”">​</a></h4><ul><li>HTTP 协议主流版本</li><li>200/302/404/500 状态码含义</li><li>UA、Referer 请求头含义</li><li>HTTPS 安全原理</li></ul><h4 id="_10-2-代理服务" tabindex="-1">10.2 代理服务 <a class="header-anchor" href="#_10-2-代理服务" aria-label="Permalink to “10.2 代理服务”">​</a></h4><ul><li>代理 IP 类型</li><li>请求转发软件（Squid 等）</li><li>短效 vs 长效代理选择</li></ul><h4 id="_10-3-js-逆向" tabindex="-1">10.3 JS 逆向 <a class="header-anchor" href="#_10-3-js-逆向" aria-label="Permalink to “10.3 JS 逆向”">​</a></h4><ul><li>无限 Debugger 产生原因</li><li>JS 断点添加位置</li><li>调度 JS 代码的 Python 库</li><li>Python 重构 vs 调度 JS 适用场景</li><li>加解密算法列举</li><li>ReRes 插件工作原理</li></ul><h4 id="_10-4-cookie-管理" tabindex="-1">10.4 Cookie 管理 <a class="header-anchor" href="#_10-4-cookie-管理" aria-label="Permalink to “10.4 Cookie 管理”">​</a></h4><ul><li>Cookie 与 Session 异同</li><li>Cookie 池使用场景</li><li>Cookie 属性列举</li><li>Cookie 池管理与维护方案</li></ul><h4 id="_10-5-浏览器调度" tabindex="-1">10.5 浏览器调度 <a class="header-anchor" href="#_10-5-浏览器调度" aria-label="Permalink to “10.5 浏览器调度”">​</a></h4><ul><li>Selenium vs PhantomJS 选型</li><li>滑块验证码算法对比</li><li>Selenium 支持的浏览器</li></ul><h4 id="_10-6-数据加密" tabindex="-1">10.6 数据加密 <a class="header-anchor" href="#_10-6-数据加密" aria-label="Permalink to “10.6 数据加密”">​</a></h4><ul><li>字体渲染全过程</li><li>Base64 在网页中的应用</li></ul><h4 id="_10-7-分布式爬虫" tabindex="-1">10.7 分布式爬虫 <a class="header-anchor" href="#_10-7-分布式爬虫" aria-label="Permalink to “10.7 分布式爬虫”">​</a></h4><ul><li>Scrapy 框架组件</li><li>下载器中间件职责</li><li>分布式爬虫适用场景</li><li>Scrapyd 是什么</li><li>分布式爬虫管理系统列举</li></ul><h4 id="_10-8-大数据" tabindex="-1">10.8 大数据 <a class="header-anchor" href="#_10-8-大数据" aria-label="Permalink to “10.8 大数据”">​</a></h4><ul><li>Spark 优势</li><li>分布式文件系统 vs 大数据文件系统</li><li>HBase vs Hive 差异与适用场景</li></ul><h3 id="本章知识点-9" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点-9" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>全课程知识点体系化复盘</li><li>30 道测验题覆盖所有核心模块</li></ul><hr><h2 id="第十一章-爬虫工程师简历指导" tabindex="-1">第十一章：爬虫工程师简历指导 <a class="header-anchor" href="#第十一章-爬虫工程师简历指导" aria-label="Permalink to “第十一章：爬虫工程师简历指导”">​</a></h2><h3 id="教学目标-10" tabindex="-1">教学目标 <a class="header-anchor" href="#教学目标-10" aria-label="Permalink to “教学目标”">​</a></h3><ol><li>掌握爬虫工程师简历制作要点</li><li>明确后续学习路线与资料推荐</li><li>制定个人成长计划</li></ol><h3 id="章节内容-10" tabindex="-1">章节内容 <a class="header-anchor" href="#章节内容-10" aria-label="Permalink to “章节内容”">​</a></h3><h4 id="_11-1-简历制作" tabindex="-1">11.1 简历制作 <a class="header-anchor" href="#_11-1-简历制作" aria-label="Permalink to “11.1 简历制作”">​</a></h4><ul><li>一个合格的爬虫平台负责人的简历应该是怎样的？</li><li>爬虫工程师简历核心要素： <ul><li>技术栈描述规范</li><li>项目经验量化（抓取量、QPS、反爬突破）</li><li>架构设计能力体现</li><li>团队管理经验</li></ul></li></ul><h4 id="_11-2-课程总结" tabindex="-1">11.2 课程总结 <a class="header-anchor" href="#_11-2-课程总结" aria-label="Permalink to “11.2 课程总结”">​</a></h4><ul><li>课程总结及实用学习建议</li><li>核心知识点回顾</li><li>爬虫技术发展趋势</li></ul><h4 id="_11-3-后续学习" tabindex="-1">11.3 后续学习 <a class="header-anchor" href="#_11-3-后续学习" aria-label="Permalink to “11.3 后续学习”">​</a></h4><ul><li>后续学习方法/资料/课程推荐</li><li>进阶方向： <ul><li>反爬深度研究（AST 混淆、WebAssembly）</li><li>大数据架构（Spark / Flink）</li><li>机器学习辅助反爬（行为特征识别）</li><li>爬虫架构师（分布式系统设计）</li></ul></li></ul><h3 id="本章知识点-10" tabindex="-1">本章知识点 <a class="header-anchor" href="#本章知识点-10" aria-label="Permalink to “本章知识点”">​</a></h3><ul><li>爬虫工程师简历规范</li><li>职业发展路径</li><li>持续学习资源推荐</li></ul><hr><h2 id="四大实战案例汇总" tabindex="-1">四大实战案例汇总 <a class="header-anchor" href="#四大实战案例汇总" aria-label="Permalink to “四大实战案例汇总”">​</a></h2><h3 id="案例一-squid-vps-加密代理池搭建" tabindex="-1">案例一：Squid + VPS 加密代理池搭建 <a class="header-anchor" href="#案例一-squid-vps-加密代理池搭建" aria-label="Permalink to “案例一：Squid + VPS 加密代理池搭建”">​</a></h3><ul><li><strong>关联章节</strong>：第三章</li><li><strong>核心技能</strong>：Squid 部署、代理认证、代理池架构、可用性检测</li></ul><h3 id="案例二-逆向破解真实网站加密登录" tabindex="-1">案例二：逆向破解真实网站加密登录 <a class="header-anchor" href="#案例二-逆向破解真实网站加密登录" aria-label="Permalink to “案例二：逆向破解真实网站加密登录”">​</a></h3><ul><li><strong>关联章节</strong>：第四章</li><li><strong>核心技能</strong>：JS 逆向分析、无限 Debugger 突破、断点调试、Python 重构/调度 JS</li></ul><h3 id="案例三-高并发-cookie-池管理系统" tabindex="-1">案例三：高并发 Cookie 池管理系统 <a class="header-anchor" href="#案例三-高并发-cookie-池管理系统" aria-label="Permalink to “案例三：高并发 Cookie 池管理系统”">​</a></h3><ul><li><strong>关联章节</strong>：第五章</li><li><strong>核心技能</strong>：Cookie 持久化、协助式提取、Cookie 池架构、高并发有效性维护</li></ul><h3 id="案例四-scrapy-分布式爬虫综合实战" tabindex="-1">案例四：Scrapy + 分布式爬虫综合实战 <a class="header-anchor" href="#案例四-scrapy-分布式爬虫综合实战" aria-label="Permalink to “案例四：Scrapy + 分布式爬虫综合实战”">​</a></h3><ul><li><strong>关联章节</strong>：第八章</li><li><strong>核心技能</strong>：Scrapy 框架、Middleware 开发、Scrapy-Redis、Scrapyd 部署</li></ul><hr><h2 id="学习路径建议" tabindex="-1">学习路径建议 <a class="header-anchor" href="#学习路径建议" aria-label="Permalink to “学习路径建议”">​</a></h2><h3 id="阶段一-基础准备-第-1-2-章" tabindex="-1">阶段一：基础准备（第 1-2 章） <a class="header-anchor" href="#阶段一-基础准备-第-1-2-章" aria-label="Permalink to “阶段一：基础准备（第 1-2 章）”">​</a></h3><ul><li>第一章：课程导学 + 环境搭建</li><li>第二章：HTTP 网络基础（HTTPS、状态码、请求头、证书）</li></ul><h3 id="阶段二-反爬基础设施-第-3-5-章" tabindex="-1">阶段二：反爬基础设施（第 3-5 章） <a class="header-anchor" href="#阶段二-反爬基础设施-第-3-5-章" aria-label="Permalink to “阶段二：反爬基础设施（第 3-5 章）”">​</a></h3><ul><li>第三章：代理服务搭建（Squid + 代理池）</li><li>第四章：加密登录破解（JS 逆向 + Python 重构）</li><li>第五章：Cookie 池管理（持久化 + 高并发维护）</li></ul><h3 id="阶段三-浏览器与数据解密-第-6-7-章" tabindex="-1">阶段三：浏览器与数据解密（第 6-7 章） <a class="header-anchor" href="#阶段三-浏览器与数据解密-第-6-7-章" aria-label="Permalink to “阶段三：浏览器与数据解密（第 6-7 章）”">​</a></h3><ul><li>第六章：浏览器调度（Selenium + Puppeteer + 验证码识别）</li><li>第七章：数据加密破解（字体加密 + Base64）</li></ul><h3 id="阶段四-综合实战与架构-第-8-9-章" tabindex="-1">阶段四：综合实战与架构（第 8-9 章） <a class="header-anchor" href="#阶段四-综合实战与架构-第-8-9-章" aria-label="Permalink to “阶段四：综合实战与架构（第 8-9 章）”">​</a></h3><ul><li>第八章：反爬综合实战（Scrapy + Cookie 池 + 分布式）</li><li>第九章：分布式架构方案（存储 + 下游消费）</li></ul><h3 id="阶段五-复盘与求职-第-10-11-章" tabindex="-1">阶段五：复盘与求职（第 10-11 章） <a class="header-anchor" href="#阶段五-复盘与求职-第-10-11-章" aria-label="Permalink to “阶段五：复盘与求职（第 10-11 章）”">​</a></h3><ul><li>第十章：终极测验（30 题查漏补缺）</li><li>第十一章：简历指导 + 后续学习路线</li></ul><hr><h2 id="技术栈全景" tabindex="-1">技术栈全景 <a class="header-anchor" href="#技术栈全景" aria-label="Permalink to “技术栈全景”">​</a></h2><h3 id="核心语言与标准库" tabindex="-1">核心语言与标准库 <a class="header-anchor" href="#核心语言与标准库" aria-label="Permalink to “核心语言与标准库”">​</a></h3><ul><li>Python 3.x</li><li><code>http.cookiejar</code> / <code>http.client</code> / <code>ssl</code></li><li><code>base64</code> / <code>hashlib</code> / <code>hmac</code></li><li><code>asyncio</code> / <code>aiohttp</code></li><li><code>subprocess</code></li></ul><h3 id="爬虫框架" tabindex="-1">爬虫框架 <a class="header-anchor" href="#爬虫框架" aria-label="Permalink to “爬虫框架”">​</a></h3><ul><li><strong>Scrapy</strong>：企业级爬虫框架</li><li><strong>Scrapy-Redis</strong>：分布式爬虫方案</li><li><strong>Scrapyd</strong>：爬虫部署与管理</li><li><strong>Gerapy / Crawlab</strong>：分布式爬虫管理系统</li></ul><h3 id="浏览器自动化" tabindex="-1">浏览器自动化 <a class="header-anchor" href="#浏览器自动化" aria-label="Permalink to “浏览器自动化”">​</a></h3><ul><li><strong>Selenium</strong>：浏览器自动化测试框架</li><li><strong>Puppeteer</strong>（Node.js）：Headless Chrome 操作</li><li><strong>Playwright</strong>：新一代浏览器自动化</li><li><strong>undetected-chromedriver</strong>：Selenium 反检测</li></ul><h3 id="js-逆向工具" tabindex="-1">JS 逆向工具 <a class="header-anchor" href="#js-逆向工具" aria-label="Permalink to “JS 逆向工具”">​</a></h3><ul><li><strong>Chrome DevTools</strong>：浏览器开发者工具</li><li><strong>execjs / PyExecJS</strong>：Python 执行 JS</li><li><strong>ReRes</strong>：JS 文件篡改插件</li><li><strong>Tampermonkey</strong>：油猴脚本</li><li><strong>Fiddler / Charles</strong>：抓包与 Map Local</li></ul><h3 id="代理与网络" tabindex="-1">代理与网络 <a class="header-anchor" href="#代理与网络" aria-label="Permalink to “代理与网络”">​</a></h3><ul><li><strong>Squid</strong>：代理服务软件</li><li><strong>VPS</strong>：代理节点服务器</li><li><strong>代理 IP 服务商</strong>：快代理 / 芝麻代理 / 讯代理等</li></ul><h3 id="数据存储" tabindex="-1">数据存储 <a class="header-anchor" href="#数据存储" aria-label="Permalink to “数据存储”">​</a></h3><ul><li><strong>关系型</strong>：MySQL / PostgreSQL</li><li><strong>文档型</strong>：MongoDB</li><li><strong>搜索引擎</strong>：Elasticsearch</li><li><strong>缓存</strong>：Redis</li><li><strong>对象存储</strong>：MinIO / OSS / S3</li><li><strong>大数据</strong>：HBase / Hive / ClickHouse / Spark</li></ul><h3 id="图像处理" tabindex="-1">图像处理 <a class="header-anchor" href="#图像处理" aria-label="Permalink to “图像处理”">​</a></h3><ul><li><strong>Pillow (PIL)</strong>：Python 图像处理库</li><li><strong>OpenCV</strong>：计算机视觉</li><li><strong>Rembrandt</strong>：图像相似度比较</li><li><strong>SSIM</strong>：结构相似性算法</li></ul><hr><h2 id="面试要点汇总" tabindex="-1">面试要点汇总 <a class="header-anchor" href="#面试要点汇总" aria-label="Permalink to “面试要点汇总”">​</a></h2><h3 id="高频面试题" tabindex="-1">高频面试题 <a class="header-anchor" href="#高频面试题" aria-label="Permalink to “高频面试题”">​</a></h3><ol><li><strong>HTTP 基础</strong>：HTTPS 加密原理、状态码含义、请求头反爬识别、HTTP/2 多路复用</li><li><strong>代理服务</strong>：Squid 搭建流程、代理池架构设计、短效 vs 长效代理选择、高匿代理原理</li><li><strong>JS 逆向</strong>：无限 Debugger 突破方法、JS 断点调试流程、ReRes 工作原理、execjs vs PyExecJS 选型</li><li><strong>Cookie 管理</strong>：Cookie vs Session、Cookie 池架构、高并发 Cookie 有效性维护、Cookie 属性</li><li><strong>浏览器调度</strong>：Selenium vs Puppeteer 选型、Chrome 远程调试原理、CDP 协议</li><li><strong>验证码识别</strong>：滑动验证码原理、RGB/Rembrandt/SSIM 算法对比、贝塞尔曲线轨迹模拟</li><li><strong>数据加密</strong>：字体渲染流程、字体加密反爬原理、cmap 表解析、动态字体处理</li><li><strong>Scrapy 框架</strong>：架构组件、Middleware 开发、Pipeline 数据处理</li><li><strong>分布式爬虫</strong>：Scrapy-Redis 原理、Scrapyd 部署、分布式任务调度</li><li><strong>数据存储</strong>：MySQL vs MongoDB vs ES 选型、HBase vs Hive 差异、Spark 优势</li></ol><h3 id="实战能力清单" tabindex="-1">实战能力清单 <a class="header-anchor" href="#实战能力清单" aria-label="Permalink to “实战能力清单”">​</a></h3><ul><li>[ ] 能独立搭建 Squid 代理池并封装 Python 接口</li><li>[ ] 能逆向分析 JS 加密逻辑并用 Python 重构</li><li>[ ] 能搭建管理上万 Cookie 的高并发 Cookie 池</li><li>[ ] 能用 Puppeteer 实现滑动验证码自动识别</li><li>[ ] 能破解字体加密并批量还原数据</li><li>[ ] 能用 Scrapy + Redis 搭建分布式爬虫</li><li>[ ] 能用 Scrapyd 部署和管理爬虫服务</li><li>[ ] 能设计完整的数据存储与下游消费方案</li></ul><hr><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to “附录”">​</a></h2><h3 id="推荐学习资源" tabindex="-1">推荐学习资源 <a class="header-anchor" href="#推荐学习资源" aria-label="Permalink to “推荐学习资源”">​</a></h3><ul><li>《Python3 网络爬虫开发实战》— 崔庆才</li><li>《爬虫逆向进阶实战》— 李玺</li><li>《Web Scraping with Python》— Ryan Mitchell</li><li>Scrapy 官方文档（docs.scrapy.org）</li><li>Puppeteer 官方文档（pptr.dev）</li><li>Chrome DevTools 文档（developers.google.com/web/tools/chrome-devtools）</li></ul><h3 id="实践项目建议" tabindex="-1">实践项目建议 <a class="header-anchor" href="#实践项目建议" aria-label="Permalink to “实践项目建议”">​</a></h3><ul><li>电商商品价格监控（代理池 + Cookie 池 + 分布式）</li><li>社交媒体舆情采集（加密登录 + 浏览器调度 + 数据解密）</li><li>招聘网站岗位聚合（Scrapy + Redis + Elasticsearch）</li><li>新闻资讯聚合平台（全链路：采集 → 清洗 → 存储 → 检索）</li><li>金融数据实时抓取（高并发 + 分布式 + 大数据存储）</li></ul><h3 id="课程对比-python-高级爬虫-vs-python-实战训练营" tabindex="-1">课程对比：Python 高级爬虫 vs Python 实战训练营 <a class="header-anchor" href="#课程对比-python-高级爬虫-vs-python-实战训练营" aria-label="Permalink to “课程对比：Python 高级爬虫 vs Python 实战训练营”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Python 高级爬虫实战</th><th>Python 实战训练营</th></tr></thead><tbody><tr><td>定位</td><td>爬虫工程师进阶</td><td>Python 全栈工程师进阶</td></tr><tr><td>核心技能</td><td>反爬破解、JS 逆向、分布式爬虫</td><td>Web 框架、ORM、异步、微服务</td></tr><tr><td>难度</td><td>高级</td><td>中高级</td></tr><tr><td>时长</td><td>22.5 小时</td><td>96 小时（16周）</td></tr><tr><td>侧重</td><td>数据采集层</td><td>应用开发层</td></tr><tr><td>分布式</td><td>Scrapy-Redis 分布式爬虫</td><td>gRPC 微服务 + 分布式锁</td></tr><tr><td>数据处理</td><td>数据存储与下游消费</td><td>ETL 数据管道 + Airflow</td></tr><tr><td>工程化</td><td>Scrapyd 部署管理</td><td>Docker + K8s + CI/CD</td></tr></tbody></table><blockquote><p><strong>互补关系</strong>：爬虫课程侧重数据采集与反爬，训练营课程侧重应用开发与架构。两者结合可覆盖从数据采集到应用的完整链路。</p></blockquote>',294)])])}const P=i(o,[["render",h]]);export{u as __pageData,P as default};
